  // LOGO-PACK: lineTotal = 120000, discount = 0
  // subtotal = 215000, total discount = 9500, total = 205500
  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.total, 205500);
});

test('invoiceTotals clamps total to zero when discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 100,
        vatRate: 21,
        discountPercent: 100,
      },
    ],
  };
